<template>
  <div class="hot-money">
    <header class="panel intro"><div><span class="eyebrow">席位披露 / 关注联动</span><h2>游资动向</h2><p>先看与你有关的变化，再核对每一份龙虎榜披露。</p></div><div class="tools"><button :disabled="loading" @click="refresh">刷新记录</button><button :disabled="syncing || !!data && !data.job.can_start" @click="sync">核对最近三日</button><router-link :to="{path:'/',query:{tab:'short-term',mode:'close',date}}">查看站内提醒 →</router-link></div></header>
    <p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message notice" role="status">{{ notice }}</p>
    <template v-if="data">
      <section class="panel status"><div class="tools"><b>{{ date }} · {{ data.batch_id?'已缓存公开披露':'等待披露入库' }}</b><span>采集 {{ time(data.fetched_at) }}</span><span v-if="data.catalog_id">名录 #{{ data.catalog_id }} · {{ time(data.catalog_at) }}</span></div><p v-if="data.check" :class="{error:data.check.status==='error',notice:data.check.status==='waiting'}">{{ data.check.message }} · 最近核对 {{ time(data.check.checked_at) }}</p><p v-if="['running','queued'].includes(data.job.status)" class="notice">采集任务{{ data.job.status==='queued'?'已提交':'运行中' }}，正在等待真实结果。</p><p v-if="data.quality">覆盖 {{ data.quality.stocks }} 只 A 股、{{ data.quality.reports }} 份披露单；{{ data.quality.warnings }} 份有待核对项。名录关联 {{ data.quality.mapped_records }} / {{ data.quality.seat_records }} 条席位记录。</p><p>{{ data.method }}</p><small>{{ data.scope_note }}</small></section>
      <div class="metrics"><button class="panel" @click="setScope('mine')"><span>我的关注股命中</span><b>{{ data.counts.mine }}</b><small>当前自选及待验证观察</small></button><button class="panel" @click="setScope('followed')"><span>关注席位命中</span><b>{{ data.counts.followed }}</b><small>游资名录关联或营业部</small></button><div class="panel"><span>较大披露净卖出</span><b>{{ data.counts.large_sell }}</b><small>所选口径净卖出 ≥ 5000 万元</small></div><button class="panel" @click="setScope('all')"><span>全部披露股票</span><b>{{ data.counts.stocks }}</b><small>{{ period==='day'?'单日披露':'多日累计披露' }}</small></button></div>
      <section class="panel"><div class="section-head"><h3>所选日重点</h3><span>按当前关注范围优先，最多展示 8 条</span></div><div v-if="data.focus.length" class="focus-grid"><button v-for="item in data.focus" :key="item.code+item.period" class="focus" @click="openStock(item.code,item.date,item.batch_id)"><div><strong>{{ item.name }}</strong><small>{{ item.code }}</small><span class="chip">{{ item.watched?'关注股':'关注席位' }}</span></div><b :class="tone(item.net)">{{ amount(item.net) }}</b><p>{{ item.names.join('、') || '营业部明细待展开核对' }}</p><small>{{ item.tags.join(' · ') || item.reason }}</small></button></div><p v-else class="empty">所选口径暂未命中你的关注范围。可浏览下方全部记录，关注游资或具体营业部；未命中不代表没有交易。</p></section>
      <section class="panel"><div class="tools filters"><h3>个股动向</h3><select v-model="period" aria-label="披露口径"><option value="day">单日披露</option><option value="multi">多日累计披露</option></select><select v-model="scope" aria-label="关注范围"><option value="all">全部 A 股 · 关注优先</option><option value="mine">我的自选／观察池</option><option value="followed">关注游资／营业部</option></select><form @submit.prevent="applySearch"><input v-model="searchDraft" maxlength="100" placeholder="股票、游资或营业部" aria-label="查找披露" /><button>查找</button></form><span v-if="loading">读取中…</span></div><p v-if="period==='multi'" class="notice">本表为多日累计披露，金额覆盖上榜原因所述区间，不与单日金额合计。</p><div class="table-wrap"><table><thead><tr><th>股票</th><th>涨跌幅／连板</th><th>披露净额</th><th>名录关联游资</th><th>变化与范围</th><th>操作</th></tr></thead><tbody><tr v-for="item in data.items" :key="item.code+item.period"><td><button class="link stock" @click="openStock(item.code,item.date,item.batch_id)">{{ item.name }}</button><small>{{ item.code }}</small></td><td><span :class="tone(item.change_pct)">{{ pct(item.change_pct) }}</span><small>{{ item.height?item.height+' 连板':'—' }}</small></td><td :class="tone(item.net)"><b>{{ amount(item.net) }}</b><small>机构披露净额 {{ amount(item.institution_net) }}</small></td><td><template v-if="item.names.length"><button v-for="name in item.names" :key="name" class="link person" @click="openHistory('person',name)">{{ name }}</button></template><span v-else class="muted">暂未关联，查看营业部</span></td><td><span v-if="item.watched" class="chip">我的关注</span><span v-if="item.followed" class="chip">关注席位</span><small v-for="tag in item.tags" :key="tag">{{ tag }}</small><small v-if="item.warnings.length" class="notice">{{ item.warnings.join('；') }}</small></td><td class="row-actions"><button @click="openStock(item.code,item.date,item.batch_id)">看席位</button><button @click="$emit('addWatchlist',item.code)">加自选</button><router-link v-if="item.observations.length" :to="{path:'/review',query:{date,observation:item.observations[0].id}}">查看观察 →</router-link><button v-else @click="observe(item)">加入复盘观察</button></td></tr></tbody></table></div><p v-if="!data.items.length" class="empty">当前筛选下没有本地披露记录。请结合采集状态和数据覆盖核对。</p><div v-if="data.pages>1" class="tools pager"><button :disabled="page<=1||loading" @click="page--">上一页</button><span>{{ data.page }} / {{ data.pages }} · {{ data.total }} 只</span><button :disabled="page>=data.pages||loading" @click="page++">下一页</button></div></section>
      <section class="panel"><div class="section-head"><h3>我的游资／席位关注</h3><span>关注后，后续新披露可进入短线异动的收盘提醒</span></div><div class="tools"><select v-model="catalogName" aria-label="选择游资名录"><option value="">从名录选择游资</option><option v-for="entry in catalog?.items || []" :key="entry.name" :value="entry.name">{{ entry.name }} · {{ entry.orgs.length }} 个关联营业部</option></select><button :disabled="!catalogName||!!working" @click="toggleFollow('person',catalogName,true)">关注</button><button :disabled="!catalogName" @click="openHistory('person',catalogName)">查看披露</button></div><div class="follow-list"><div v-for="item in data.follows" :key="item.kind+item.subject"><button class="link" @click="openHistory(item.kind,item.subject)">{{ item.subject }}</button><small>{{ item.kind==='person'?'名录关联':'具体营业部' }}</small><button :disabled="!!working" @click="toggleFollow(item.kind,item.subject,false)">取消关注</button></div></div><p v-if="!data.follows.length" class="muted">尚未关注席位。未关联游资名称的营业部也可以在个股详情中单独关注。</p></section>
      <details class="panel"><summary>覆盖与统计口径</summary><p>{{ data.limitation }}</p><p>近 20 个交易日已缓存 {{ data.coverage.cached_dates.length }} 日；{{ data.coverage.calendar_known?'官方日历已取得':'官方日历待核对' }}。{{ data.coverage.complete?'窗口资料齐备，可识别窗口首次披露。':'资料不足时不标记首次披露。' }}</p><p>“连续净买”只检查相邻真实交易日的单日披露。“由买转卖”比较窗口内最近两次披露，不代表中间没有交易。不同“机构专用”记录保留为匿名机构，不能认定为同一资金。</p><p>复盘 AI 手动审阅会引用最近五个交易日的本地披露、来源版本和覆盖说明；打开页面、关注和刷新均不调用模型。</p></details>
    </template><p v-else-if="loading" class="empty">正在整理游资与席位披露…</p>

    <section v-if="detailLoading || detail" ref="detailPanel" class="panel detail"><div class="section-head"><h3>个股披露详情</h3><button @click="closeDetail">关闭详情</button></div><p v-if="detailLoading">正在读取保存的披露版本…</p><template v-else-if="detail"><div class="tools"><b>{{ detail.code }} · {{ detail.date }}</b><label>保存版本 <select :value="detail.batch_id" @change="switchVersion"><option v-for="version in detail.versions" :key="version.id" :value="version.id">#{{ version.id }} · {{ time(version.fetched_at) }}</option></select></label><router-link :to="'/stock/'+detail.code">当前个股详情 →</router-link></div><p>名录 #{{ detail.catalog_id }}，核对于 {{ time(detail.catalog_at) }}。{{ detail.limitation }}</p><article v-for="report in detail.reports" :key="report.reason" class="report"><div class="tools"><span class="chip">{{ report.period==='day'?'单日':'多日累计' }}</span><strong>{{ report.reason }}</strong><span v-if="report.selected" class="muted">本口径汇总选单</span></div><p>披露买入 {{ amount(report.buy) }} · 卖出 {{ amount(report.sell) }} · 净额 <b :class="tone(report.net)">{{ amount(report.net) }}</b></p><p v-for="warning in report.warnings" :key="warning" class="notice">{{ warning }}</p><div class="table-wrap"><table><thead><tr><th>营业部／关联名录</th><th>买入</th><th>卖出</th><th>净额</th><th>跟踪</th></tr></thead><tbody><tr v-for="(seat,index) in report.seats" :key="index"><td>{{ seat.seat }}<small>{{ associationLabels[seat.association] }}{{ seat.names.length?' · '+seat.names.join('、'):'' }}</small><small v-if="seat.conflict" class="notice">同名席位金额冲突，保留记录，历史汇总不计入</small></td><td>{{ amount(seat.buy) }}</td><td>{{ amount(seat.sell) }}</td><td :class="tone(seat.net)">{{ amount(seat.net) }}</td><td><template v-if="seat.type==='seat'"><button @click="openHistory('seat',seat.seat)">看历史</button><button :disabled="!!working" @click="toggleFollow('seat',seat.seat,!isFollowed('seat',seat.seat))">{{ isFollowed('seat',seat.seat)?'取消关注':'关注营业部' }}</button><button v-for="name in seat.association==='catalog'?seat.names:[]" :key="name" @click="openHistory('person',name)">{{ name }} →</button></template><small v-else>匿名／集合席位不作为单一资金关注</small></td></tr></tbody></table></div></article><details><summary>核对原始接口记录（金额单位元）</summary><pre>{{ JSON.stringify(detail.raw,null,2) }}</pre></details></template></section>

    <section v-if="historySubject" ref="historyPanel" class="panel"><div class="section-head"><h3>{{ historySubject }} · 披露轨迹</h3><button @click="closeHistory">关闭历史</button></div><div class="tools"><select v-model.number="historyDays" aria-label="历史交易日窗口"><option :value="5">近 5 个交易日</option><option :value="10">近 10 个交易日</option><option :value="20">近 20 个交易日</option></select><button :disabled="!!working" @click="toggleFollow(historyKind,historySubject,!isFollowed(historyKind,historySubject))">{{ isFollowed(historyKind,historySubject)?'取消关注':'关注此对象' }}</button></div><p v-if="historyLoading">正在读取轨迹…</p><template v-else-if="history"><p>窗口已缓存 {{ history.coverage.cached_dates.length }} 日；{{ history.coverage.complete?'窗口资料齐备':'覆盖不完整，空白日期不代表未交易' }}。单日与累计分列，不合计为持仓。</p><div class="table-wrap"><table><thead><tr><th>日期</th><th>股票</th><th>披露口径</th><th>买入</th><th>卖出</th><th>净额</th><th>名录版本</th></tr></thead><tbody><tr v-for="(item,index) in history.items" :key="index"><td>{{ item.date }}</td><td><button class="link" @click="openStock(item.code,item.date,item.batch_id)">{{ item.name }}</button><small>{{ item.seats.join('、') }}</small></td><td>{{ item.period==='day'?'单日':'多日累计' }}</td><td>{{ amount(item.buy) }}</td><td>{{ amount(item.sell) }}</td><td :class="tone(item.net)">{{ amount(item.net) }}</td><td>#{{ item.catalog_id }}</td></tr></tbody></table></div><p v-if="!history.items.length" class="empty">已缓存窗口内未找到可汇总的匹配记录；金额冲突的席位不强行合并。</p></template></section>

    <section v-if="observation" ref="observationPanel" class="panel"><div class="section-head"><h3>加入复盘观察 · {{ observation.name }}</h3><button @click="observation=null">取消</button></div><form class="observation-form" @submit.prevent="saveObservation"><label>原始披露与关注理由<textarea v-model="observationForm.reason" rows="4" maxlength="2000" required /></label><label>待验证条件<textarea v-model="observationForm.criterion" rows="2" maxlength="2000" placeholder="写下后续要验证什么，AI 不会自动把席位买入当成上涨依据" required /></label><label>验证期限<input type="date" v-model="observationForm.deadline" :min="date" required /></label><p class="muted">所属观察日 {{ date }}，实际录入时间另行保留；事后补录不会当作当时已知判断。</p><button :disabled="!!working" type="submit">确认加入观察</button></form></section>
  </div>
</template>

<script setup lang="ts">
import {nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {createLatestLoader} from '../../utils/latestLoader'
import {fetchHotMoney,fetchHotMoneyCatalog,fetchSeatHistory,fetchSeatStock,saveSeatFollow,syncHotMoney,createReviewObservation} from '../../api/client'
import type {HotMoneyDashboard,SeatStock,SeatStockDetail,SeatHistory} from '../../api/client'
const props=defineProps<{date:string}>(),emit=defineEmits<{addWatchlist:[code:string];changed:[]}>(),router=useRouter(),route=useRoute()
const data=ref<HotMoneyDashboard|null>(null),loading=ref(false),error=ref(''),notice=ref(''),scope=ref('all'),period=ref('day'),page=ref(1),searchDraft=ref(''),search=ref(''),working=ref(''),syncing=ref(false)
const catalog=ref<Awaited<ReturnType<typeof fetchHotMoneyCatalog>>|null>(null),catalogName=ref('')
const detail=ref<SeatStockDetail|null>(null),detailLoading=ref(false),detailPanel=ref<HTMLElement|null>(null),detailCode=ref(''),detailDate=ref('')
const history=ref<SeatHistory|null>(null),historyLoading=ref(false),historySubject=ref(''),historyKind=ref<'person'|'seat'>('person'),historyDays=ref(20),historyPanel=ref<HTMLElement|null>(null)
const observation=ref<SeatStock|null>(null),observationPanel=ref<HTMLElement|null>(null),observationForm=ref({reason:'',criterion:'',deadline:''})
const associationLabels:Record<string,string>={catalog:'名录关联',ambiguous:'关联有歧义，待确认',unmapped:'暂未关联游资',anonymous:'匿名机构，非同一身份',collective:'集合席位'}
let disposed=false,generation=0,timer:ReturnType<typeof setInterval>|undefined
const loader=createLatestLoader<HotMoneyDashboard>({pending:value=>loading.value=value,resolve:value=>{data.value=value;page.value=value.page;emit('changed')},reject:()=>error.value='游资披露读取失败，请刷新重试。'})
const catalogLoader=createLatestLoader<Awaited<ReturnType<typeof fetchHotMoneyCatalog>>>({resolve:value=>catalog.value=value,reject:()=>error.value='名录读取失败，请刷新重试。'})
const detailLoader=createLatestLoader<SeatStockDetail>({pending:value=>detailLoading.value=value,resolve:value=>detail.value=value,reject:()=>error.value='所选股票披露或保存版本读取失败，请重试。'})
const historyLoader=createLatestLoader<SeatHistory>({pending:value=>historyLoading.value=value,resolve:value=>history.value=value,reject:()=>error.value='席位轨迹读取失败，请重试。'})
function amount(value:string|null){if(value===null)return '未知';const n=Number(value);if(!Number.isFinite(n))return '未知';const abs=Math.abs(n),unit=abs>=1e8?'亿':abs>=1e4?'万':'元',base=abs>=1e8?1e8:abs>=1e4?1e4:1;return (n/base).toLocaleString('zh-CN',{maximumFractionDigits:2})+unit}
function pct(value:string|null){return value===null?'—':Number(value).toFixed(2)+'%'}
function tone(value:string|null){return value===null?'muted':Number(value)>0?'up':Number(value)<0?'down':'muted'}
function time(value?:string|null){return value?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value)):'—'}
function message(e:any,fallback:string){return typeof e?.response?.data?.detail==='string'?e.response.data.detail:fallback}
function refresh(){error.value='';return loader.load(signal=>fetchHotMoney({date:props.date,scope:scope.value,period:period.value,search:search.value,page:page.value},signal))}
function setScope(value:string){scope.value=value}
function applySearch(){search.value=searchDraft.value.trim()}
function isFollowed(kind:'person'|'seat',subject:string){return !!data.value?.follows.some(item=>item.kind===kind&&item.subject===subject)}
async function toggleFollow(kind:'person'|'seat',subject:string,active:boolean){if(working.value)return;const current=generation;working.value='follow';error.value='';try{await saveSeatFollow(kind,subject,active);if(disposed||current!==generation)return;notice.value=active?'已关注。后续同步时，相关新披露会进入收盘提醒；历史记录不补发新行情通知。':'已取消关注，原提醒与披露历史保留。';await refresh()}catch(e){if(!disposed&&current===generation)error.value=message(e,'关注状态保存结果未确认，请刷新核对。')}finally{if(current===generation)working.value=''}}
async function sync(){if(syncing.value)return;const current=generation;syncing.value=true;try{const result=await syncHotMoney();if(disposed||current!==generation)return;notice.value=result.accepted?'后台核对已提交，正在等待执行结果。':'复用了正在执行或刚提交的任务。';await refresh()}catch(e){if(!disposed&&current===generation)error.value=message(e,'提交结果尚未确认，请刷新任务状态。')}finally{if(current===generation)syncing.value=false}}
async function openStock(code:string,date:string,batch?:number){detail.value=null;detailCode.value=code;detailDate.value=date;await detailLoader.load(signal=>fetchSeatStock(code,date,batch,signal));await nextTick();detailPanel.value?.scrollIntoView({behavior:'smooth',block:'start'})}
function switchVersion(event:Event){openStock(detailCode.value,detailDate.value,Number((event.target as HTMLSelectElement).value))}
function closeDetail(){detailLoader.cancel();detail.value=null;detailCode.value=''}
async function openHistory(kind:'person'|'seat',subject:string){historyKind.value=kind;historySubject.value=subject;history.value=null;await loadHistory();await nextTick();historyPanel.value?.scrollIntoView({behavior:'smooth',block:'start'})}
function loadHistory(){return historyLoader.load(signal=>fetchSeatHistory(props.date,historyKind.value,historySubject.value,historyDays.value,signal))}
function closeHistory(){historyLoader.cancel();historySubject.value='';history.value=null}
async function observe(item:SeatStock){observation.value=item;const deadline=new Date(props.date+'T00:00:00Z');deadline.setUTCDate(deadline.getUTCDate()+7);observationForm.value={reason:`${item.date} ${item.period==='day'?'单日':'多日累计'}龙虎榜披露，选定单据净额 ${amount(item.net)}；名录关联：${item.names.join('、')||'未确认'}。\n上榜原因：${item.reason}\n源批次 #${item.batch_id}，实际采集 ${time(item.fetched_at)}。仅为披露交易，非持仓或身份确认。\n我的关注理由：`,criterion:'',deadline:deadline.toISOString().slice(0,10)};await nextTick();observationPanel.value?.scrollIntoView({behavior:'smooth',block:'start'})}
async function saveObservation(){if(!observation.value||working.value)return;const current=generation,code=observation.value.code;working.value='observation';try{const result=await createReviewObservation({code,observation_date:props.date,...observationForm.value});if(disposed||current!==generation)return;observation.value=null;router.push({path:'/review',query:{date:props.date,observation:result.id}})}catch(e){if(!disposed&&current===generation)error.value=message(e,'关注记录保存结果未确认，请刷新复盘记录核对。')}finally{if(current===generation)working.value=''}}
watch([scope,period,search],()=>{page.value=1;refresh()})
watch(page,()=>{if(!loading.value)refresh()})
watch(historyDays,()=>{if(historySubject.value)loadHistory()})
watch(()=>[route.query.seat_stock,route.query.seat_batch],()=>{const code=route.query.seat_stock,batch=Number(route.query.seat_batch);if(typeof code==='string'&&/^\d{6}$/.test(code))openStock(code,props.date,Number.isInteger(batch)&&batch>0?batch:undefined)},{immediate:true})
watch(()=>props.date,()=>{generation++;loader.cancel();closeDetail();closeHistory();observation.value=null;working.value='';syncing.value=false;data.value=null;page.value=1;notice.value='';refresh()})
onMounted(()=>{refresh();catalogLoader.load(signal=>fetchHotMoneyCatalog(signal));timer=setInterval(()=>{if(!document.hidden&&!loading.value&&!working.value){refresh();if(!catalog.value?.id)catalogLoader.load(signal=>fetchHotMoneyCatalog(signal))}},30000)})
onUnmounted(()=>{disposed=true;generation++;clearInterval(timer);loader.dispose();catalogLoader.dispose();detailLoader.dispose();historyLoader.dispose()})
